/**
 * Extracts `@handle` mentions from comment bodies and resolves them to member
 * ids.
 *
 * A handle is the local part of a member's email address, lowercased — that
 * is what the comment composer autocompletes and what `CommentService` feeds
 * to the notification fan-out, so extraction and resolution must agree
 * exactly. Mentions inside code spans and fenced blocks are ignored.
 */
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";

/**
 * `@` must start the line or follow a character that cannot be part of an
 * email local part, so an address never counts as a mention. A handle is the
 * whole local part, which may be a single character and may contain `+`.
 */
const MENTION_PATTERN = /(^|[^\w.+%@-])@([a-z0-9](?:[a-z0-9._+-]{0,62}[a-z0-9])?)/gi;

function withoutCode(body: string): string {
  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
}

/** The handle Taskflow addresses a member by, derived from their email. */
export function handleOf(member: MemberWithUser): string {
  return (member.user.email.split("@")[0] ?? "").toLowerCase();
}

/** Every distinct handle mentioned, in first-appearance order. */
export function extractMentions(body: string): readonly string[] {
  const seen = new Set<string>();
  const handles: string[] = [];

  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
    const handle = (match[2] ?? "").toLowerCase();
    if (handle === "" || seen.has(handle)) continue;
    seen.add(handle);
    handles.push(handle);
  }

  return handles;
}

/**
 * Maps the mentions in `body` onto the ids of members who actually exist in
 * the organization. Unknown handles are silently dropped — a typo must never
 * fail the comment write.
 */
export function resolveMentions(
  body: string,
  members: readonly MemberWithUser[],
): readonly UserId[] {
  const byHandle = new Map<string, UserId>();
  for (const member of members) {
    // Read-only members cannot take part in a discussion, so pinging them
    // only produces an alert they can do nothing about.
    if (member.role === "viewer") continue;
    byHandle.set(handleOf(member), member.userId);
  }

  const resolved: UserId[] = [];
  const seen = new Set<UserId>();
  for (const handle of extractMentions(body)) {
    const userId = byHandle.get(handle);
    if (userId === undefined || seen.has(userId)) continue;
    seen.add(userId);
    resolved.push(userId);
  }

  return resolved;
}

/** Wraps every mention in a span so the comment renderer can style it. */
export function highlightMentions(body: string): string {
  return body.replace(
    MENTION_PATTERN,
    (_match, prefix: string, handle: string) =>
      `${prefix}<span class="mention">@${handle}</span>`,
  );
}

/**
 * The typing-side half of @-mentions.
 *
 * `@/lib/mentions` owns what a finished comment body *means* (which users it
 * mentions); this module owns what the caret is currently doing — where the
 * active `@token` starts, what it filters to, and what the body looks like
 * once a suggestion is accepted. Splitting it that way keeps the textarea from
 * re-deriving the parsing rules the server also applies.
 */
import type { MemberWithUser } from "@/types/member";

/** An in-progress mention: `@` plus the characters typed after it. */
export interface MentionQuery {
  /** Index of the `@` in the body. */
  readonly start: number;
  /** Index just past the last typed character. */
  readonly end: number;
  /** The text after `@`, lowercased for matching. */
  readonly query: string;
}

const MENTION_CHARS = /^[a-zA-Z0-9._-]*$/;

/**
 * Finds the mention the caret sits inside, or `null` when the caret is not in
 * one. A mention only starts at the beginning of the body or after
 * whitespace, so an email address never opens the autocomplete.
 */
export function findMentionQuery(
  body: string,
  caret: number,
): MentionQuery | null {
  const upTo = body.slice(0, Math.max(0, Math.min(caret, body.length)));
  const at = upTo.lastIndexOf("@");
  if (at === -1) return null;

  const before = at === 0 ? "" : upTo[at - 1] ?? "";
  if (before.length > 0 && !/\s/.test(before)) return null;

  const typed = upTo.slice(at + 1);
  if (!MENTION_CHARS.test(typed)) return null;

  return { start: at, end: upTo.length, query: typed.toLowerCase() };
}

/** The handle Taskflow mentions people by: the local part of their email. */
export function mentionHandle(member: MemberWithUser): string {
  const [local = member.user.name] = member.user.email.split("@");
  return local.toLowerCase();
}

/** Members whose handle or display name matches the in-progress query. */
export function matchMembers(
  members: readonly MemberWithUser[],
  query: string,
  limit = 5,
): readonly MemberWithUser[] {
  const needle = query.toLowerCase();
  const matches =
    needle.length === 0
      ? members
      : members.filter(
          (member) =>
            mentionHandle(member).includes(needle) ||
            member.user.name.toLowerCase().includes(needle),
        );
  return matches.slice(0, limit);
}

/** Replaces the in-progress mention with the chosen member's handle. */
export function applyMention(
  body: string,
  mention: MentionQuery,
  member: MemberWithUser,
): { body: string; caret: number } {
  const inserted = `@${mentionHandle(member)} `;
  const next = body.slice(0, mention.start) + inserted + body.slice(mention.end);
  return { body: next, caret: mention.start + inserted.length };
}

