/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by its replies. A deleted top-level comment takes its
 * thread with it — nothing to anchor the replies to once the opener is gone.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = repliesBy.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesBy.set(comment.parentId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null && comment.archivedAt === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

input.new_string:
/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply that descends from it, directly or
 * through other replies, in order of posting.
 *
 * A deleted comment keeps its place as a placeholder: it is marked by its
 * `archivedAt` and its text and mentions are blanked, so the replies under it
 * stay where they were.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(comments.id))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));
  const byId = new Map(decorated.map((comment) => [comment.id, comment]));

  // Walks up to the top-level comment a row hangs from. Null for a broken
  // chain (a parent missing from this issue), which has no place to be shown.
  const topOf = (comment: CommentWithAuthor): CommentWithAuthor | null => {
    let current = comment;
    const seen = new Set<string>();
    while (current.parentId !== null) {
      if (seen.has(current.id)) return null;
      seen.add(current.id);
      const parent = byId.get(current.parentId);
      if (parent === undefined) return null;
      current = parent;
    }
    return current;
  };

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const top = topOf(comment);
    if (top === null) continue;
    const bucket = repliesBy.get(top.id) ?? [];
    bucket.push(comment);
    repliesBy.set(top.id, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment: redactIfDeleted(comment),
      replies: (repliesBy.get(comment.id) ?? []).map(redactIfDeleted),
    }));
}

/** A deleted comment keeps its row in the thread but not its text. */
function redactIfDeleted(comment: CommentWithAuthor): CommentWithAuthor {
  if (comment.archivedAt === null) return comment;
  return { ...comment, body: "", mentionedUserIds: [] };
}

