    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });

  await notifyMentioned(payload.orgId, payload.issueId, payload.mentionedUserIds, payload.actorId);
});

subscribe("comment.updated", async (payload) => {
